def gen(rng):
    def fmt(nums, th):
        return f"{len(nums)} {th}\n" + ' '.join(map(str, nums))
    tests = [fmt([1], 1), fmt([10**6], 1), fmt([10**6], 10**6), fmt([5, 5, 5], 3), fmt([5, 5, 5], 15), fmt([1, 1, 1, 1], 4), fmt([7, 3, 10], 5)]
    for n in (2, 3, 5, 8, 12, 20):
        for _ in range(3):
            nums = [rng.randint(1, 30) for _ in range(n)]
            th = rng.randint(n, 4 * n)
            tests.append(fmt(nums, th))
    N = 100000
    tests.append(fmt([rng.randint(1, 10**6) for _ in range(N)], N))
    tests.append(fmt([rng.randint(1, 10**6) for _ in range(N)], 3 * N))
    tests.append(fmt([10**6] * N, N))
    tests.append(fmt([rng.randint(1, 10**6) for _ in range(N)], 10**6))
    tests.append(fmt([rng.randint(1, 10**6) for _ in range(2000)], 2017))
    return tests

